ma, 1e-6) vmax = min(max(v_mad, 1e-6), perc_v) else: vmax = perc_v if vmax <= 0: vmax = np.nanmax(np.abs(vals)) or 1.0 norm = SymLogNorm(linthresh=linthresh, vmin=-vmax, vmax=vmax, base=10) if scale == "symlog" else TwoSlopeNorm(vmin=-vmax, vcenter=0.0, vmax=vmax) extent = [0, n2, 0, n1] fig, axs = plt.subplots(1, 2, figsize=(10, 4), constrained_layout=True) im0 = axs[0].imshow(R_low, origin="lower", cmap=cmap, norm=norm, extent=extent, interpolation="nearest") axs[0].set_title(f"{pop_label} low-effect residuals") axs[0].set_xlabel(f"{pop_label}23 (j)") axs[0].set_ylabel(f"{pop_label}02 (i)") im1 = axs[1].imshow(R_high, origin="lower", cmap=cmap, norm=norm, extent=extent, interpolation="nearest") axs[1].set_title(f"{pop_label} high-effect residuals") axs[1].set_xlabel(f"{pop_label}23 (j)") axs[1].set_ylabel(f"{pop_label}02 (i)") for ax in axs: ax.plot([0, n2], [0, n1], color="k", lw=0.9, ls=":") ax.set_xlim(0, n2) ax.set_ylim(0, n1) ax.xaxis.set_major_locator(MaxNLocator(integer=True, nbins=6)) ax.yaxis.set_major_locator(MaxNLocator(integer=True, nbins=6)) cbar = fig.colorbar(im1, ax=axs, fraction=0.025, pad=0.02) cbar.set_label("Anscombe residual") plt.show() # Compute neutral-corrected row-wise effect sizes def residual_shift_by_row(obs, model): O = obs.data.astype(float) M = model.data.astype(float) n_y, n_x = O.shape rows = np.arange(n_y) mean_j_ratio, E_delta_ratio = [], [] for i in rows: o = O[i, :] m = M[i, :] w = (o + 1.0) / (m + 1.0) w[~np.isfinite(w)] = 0.0 if w.sum() == 0: mean_j_ratio.append(np.nan) E_delta_ratio.append(np.nan) continue j = np.arange(n_x) mean_j_ratio.append((j * w).sum() / w.sum()) E_delta_ratio.append(((j - i) * w).sum() / w.sum()) return pd.DataFrame({"row": rows, "mean_j_ratio": mean_j_ratio, "E_delta_ratio": E_delta_ratio}) # --- Main function to fit neutral model and plot residuals and neutral-corrected effect sizes --- def compare_residual_shifts(pop_label, data_low, data_high): assert np.allclose(data_low.sample_sizes, data_high.sample_sizes), f"{pop_label}: low/high SFS must have same projections" print(f"
Fitting neutral model to {pop_label} low-effect 2dSFS...") p_opt, model, ll, theta, pts_l = fit_split_mig_sym_on_low(data_low) print(f"{pop_label} best params [nu1, nu2, T, m]: {np.round(p_opt,4)}, logL={ll:.2f}, theta={theta:.3f}") plot_residual_heatmaps(data_low, data_high, model_neutral=model, pop_label=pop_label, cmap="RdBu_r", vclip_percent=96, scale="symlog", linthresh=1.0, exclude_edges=True, edge_pad=3, corner_crop=2, use_mad=True, sigma=3.5) df_low = residual_shift_by_row(data_low, model) df_high = residual_shift_by_row(data_high, model) df = df_low.merge(df_high, on="row", suffixes=("_low", "_high")) fig, axs = plt.subplots(1, 2, figsize=(11, 4), constrained_layout=True) axs[0].plot(df.row, df.mean_j_ratio_low - df.mean_j_ratio_high, 'k-o', lw=1.5, ms=4) axs[0].axhline(0, color='gray', ls=':') axs[0].set_xlabel(f"Row ({pop_label}02 i)") axs[0].set_ylabel("Δ mean j (ratio, low − high)") axs[0].set_title(f"{pop_label}: neutral-corrected mean {pop_label}23 shift") axs[1].plot(df.row, df.E_delta_ratio_low - df.E_delta_ratio_high, 'm-o', lw=1.5, ms=4) axs[1].axhline(0, color='gray', ls=':') axs[1].set_xlabel(f"Row ({pop_label}02 i)") axs[1].set_ylabel("Δ E[Δ=j−i] (ratio, low − high)") axs[1].set_title(f"{pop_label}: neutral-corrected shift relative to diagonal") plt.show() return p_opt, model, df 9.2. Call the neutral fits and residual diagnostics:¶ Show codeHide codeCopyable sourceCopy In[15]: has_params, has_model, has_resid_df = compare_residual_shifts("Has", Has_low, Has_high) Fitting neutral model to Has low-effect 2dSFS... Has best params [nu1, nu2, T, m]: [1.3810e-01 6.9900e-02 6.4000e-03 4.9897e+01], logL=-7472.98, theta=18768.029 Subsampling Low-Effect Mutations for Comparison¶To assess whether high-effect mutations differ significantly from low-effect ones, we: Subsampled the low-effect mutations to match the number of high-effect mutations. Calculated the mean effect size for each subsample. Compared the observed mean of high-effect mutations to the distribution of subsampled low-effect means. This approach evaluates whether the mean effect of high-impact variants exceeds what would be expected by chance from low-effect variants. Utility Function: Normalise Row to Probabilities Convert a row of allele counts into probabilities — ensures each row sums to 1. Show codeHide codeCopyable sourceCopy In[16]: def normalize_row(c): c = np.asarray(c, float) s = c.sum() return c / s if s > 0 else np.zeros_like(c) Generate Null Distribution via Subsampling Subsample low-effect mutations to match the count of high-effect ones and compute mean distributions. Show codeHide codeCopyable sourceCopy In[17]: def subsample_low_effect_means(sfs_low, sfs_high, row_index, n_reps=2000, rng=None): """ For a given row (i = derived allele count in pop1), - Expand low-effect mutation spectrum into a list of allele counts. - Subsample the same number as high-effect alleles. - Compute the mean allele count in pop2 for each replicate. Returns: rep_means = distribution of means (null) mean_of_means = mean of null distribution """ if rng is None: rng = np.random.default_rng(42) cH = sfs_high.data[row_index].astype(int) cL = sfs_low.data[row_index].astype(int) nH, nL = cH.sum(), cL.sum() if nH == 0 or nL == 0 or nL < nH: return None, None alleles = [] for j_value, freq in enumerate(cL): alleles.extend([j_value] * freq) rep_means = np.array([ rng.choice(alleles, size=nH, replace=False).mean() for _ in range(n_reps) ]) return rep_means, rep_means.mean() Empirical P-Value Calculation Estimate how extreme the observed mean is relative to the null distribution. Show codeHide codeCopyable sourceCopy In[18]: def calculate_empirical_p_value(observed_stat, null_dist): """ Compute two-sided empirical p-value centered around null mean. +1 pseudocount avoids zero p-values. """ n = len(null_dist) mu0 = np.mean(null_dist) extreme = np.sum(np.abs(null_dist - mu0) >= np.abs(observed_stat - mu0)) return (extreme + 1) / (n + 1) Plot Mean Comparison Visualize observed high-effect means against null distributions from low-effect subsampling. Show codeHide codeCopyable sourceCopy In[19]: def plot_mean_comparison(sfs_high, sfs_low, n_reps=2000, pop1_name="Has02", pop2_name="Has23", bins=30): """ Create grid panels (one per SFS row) showing: - Blue: null distribution from low-effect subsamples - Red: observed high-effect mean - Dashed blue: null mean - Title: permutation p-value """ n_rows = sfs_high.data.shape[0] rows = np.arange(1, n_rows) rng = np.random.default_rng(42) fig, axes = plt.subplots(6, 4, figsize=(20, 15)) axes = axes.flatten() fig.suptitle( f"Permutation Test: High vs. Low Effect Mutations ({pop1_name} → {pop2_name})", fontsize=20 ) for idx, i in enumerate(rows): ax = axes[idx] rep_means, mean_of_means = subsample_low_effect_means( sfs_low, sfs_high, i, n_reps=n_reps, rng=rng ) if rep_means is None: ax.text(0.5, 0.5, f"Row {i}
