 np.random.default_rng(42) # Extract row counts for high- and low-effect mutations cH = sfs_high.data[row_index].astype(int) cL = sfs_low.data[row_index].astype(int) # Total counts in that row nH, nL = cH.sum(), cL.sum() # Skip if too few counts if nH == 0 or nL == 0 or nL < nH: return None, None # Expand low-effect SFS row into individual allele counts alleles = [] for count_val, freq in enumerate(cL): if freq > 0: alleles.extend([count_val] * int(freq)) # Subsample repeatedly to match high-effect sample size rep_means = np.empty(n_reps, dtype=float) for r in range(n_reps): samp = rng.choice(alleles, size=nH, replace=False) rep_means[r] = samp.mean() return rep_means, float(rep_means.mean()) # === Compute two-sided permutation p-value for whether the high-effect mean is unusual compared to the null === def empirical_p_value_mean(observed_mean, null_means): # Compare observed mean to distribution of null means center = np.mean(null_means) obs_dev = abs(observed_mean - center) null_devs = np.abs(null_means - center) n = len(null_means) extreme = np.sum(null_devs >= obs_dev) return (extreme + 1) / (n + 1) # add +1 pseudocount # === Return two metrics: JSD (continuous measure of divergence between SFS shapes). Chi² p-value (significance of shape differences) === def jsd_and_chi2_from_sfs(cH, cL): # Ignore positions where both are zero mask = (cH + cL) > 0 cH_ = cH[mask].astype(float) cL_ = cL[mask].astype(float) # Normalize to probability distributions pH = normalize_row(cH_) pL = normalize_row(cL_) # Jensen-Shannon divergence (distribution similarity) try: jsd = float(jensenshannon(pH, pL, base=2.0)) except Exception: jsd = np.nan # Chi-square test (compare raw counts) try: table = np.vstack([cH_, cL_]) chi2, p_chi, dof, expected = chi2_contingency(table, correction=False) p_chi = float(p_chi) except Exception: p_chi = np.nan return jsd, p_chi # === Prepare figure with multiple subplots (each row of SFS = one subplot) === def plot_comprehensive_comparison(sfs_high, sfs_low, n_reps=2000, pop1_name="Has02", pop2_name="Has23", bins_low=10): # Number of rows in SFS (pop1 allele counts) n_rows = sfs_high.data.shape[0] rows = np.arange(1, n_rows) # skip trivial row 0 rng = np.random.default_rng(42) # Create subplot grid fig, axes = plt.subplots(6, 4, figsize=(24, 18)) fig.suptitle( f"Row-wise SFS Shape and Mean Comparison: High vs Low-effect ({pop1_name} → {pop2_name})", fontsize=22, y=0.995 ) axes = axes.flatten() # === For each row, build the null distribution of low-effect means --- # for idx, i in enumerate(rows): ax = axes[idx] # Get null distribution of subsampled low-effect means rep_means, mean_of_means = subsample_low_effect_means( sfs_low, sfs_high, i, n_reps=n_reps, rng=rng ) if rep_means is None: ax.text(0.5, 0.5, f"Row {i}
(no data)", ha='center', va='center', transform=ax.transAxes) ax.set_axis_off() continue # === Prepare the two distributions, calculates means, JSD, Chi², and permutation p-value === # Extract SFS counts cH = sfs_high.data[i].astype(float) cL = sfs_low.data[i].astype(float) # Normalize to probability distributions pH = normalize_row(cH) pL = normalize_row(cL) x = np.arange(len(pH)) # Mean of high-effect SFS mean_high = float(np.dot(x, pH)) # Compute statistics jsd, p_chi = jsd_and_chi2_from_sfs(cH, cL) p_perm = empirical_p_value_mean(mean_high, rep_means) # === Plot red = high-effect SFS, blue = low-effect SFS; histogram = subsampled low-effect means === # Plot SFS distributions ax.plot(x, pH, color='red', lw=2, label='High-effect SFS') ax.plot(x, pL, color='blue', lw=2, linestyle=':', label='Low-effect SFS') ax.axvline(mean_high, color='red', linestyle='--', lw=2, label='High-effect mean') # Second y-axis for histogram of subsampled low-effect means ax2 = ax.twinx() ax2.hist(rep_means, bins=bins_low, density=True, color='blue', alpha=0.15, edgecolor='black', linewidth=0.5, label=f'Subsampled means ({n_reps} reps)') ax2.axvline(mean_of_means, color='blue', linestyle='--', lw=2, label='Mean of subsampled means') # === Subplot title show all test results for that row === # Annotate with results ax.set_title( f"Row {i} | JSD={jsd:.3f}, χ² p={p_chi:.2e} (compare SFS shape)
" f"Permutation p={p_perm:.3f} (compare means)", fontsize=12 ) # === Clean up figure and display === for j in range(len(rows), len(axes)): fig.delaxes(axes[j]) # remove unused subplots plt.tight_layout(rect=[0, 0.02, 1, 0.96]) plt.show() 10.2. Example usage¶ Show codeHide codeCopyable sourceCopy In[22]: plot_comprehensive_comparison(Has_high, Has_low, n_reps=2000, pop1_name="Has02", pop2_name="Has23") 11 Discussion, interpretation & exercises¶Questions to think about Which effect classes show an excess of rare derived alleles in the recent timepoint (Has23)? Where do model residuals show strong deviations from the neutral expectation? How would selection vs migration shape the residual patterns? Exercises Change projections to smaller/larger values and observe smoothing of the 2dSFS. Increase bootstrap B and inspect CI stability. Modify the neutral model (allow asymmetric migration) and compare fits. Repeat the pipeline for another population or time series. (() => { document.addEventListener('click', async (event) => { const button=event.target.closest('.technical-copy-button'); if(!button)return; event.preventDefault(); event.stopPropagation(); const details=button.closest('details'); const code=details?.querySelector('pre code, pre'); if(!code)return; const text=code.innerText; try { await navigator.clipboard.writeText(text); } catch (_) { const area=document.createElement('textarea'); area.value=text; area.style.position='fixed'; area.style.opacity='0'; document.body.appendChild(area); area.select(); document.execCommand('copy'); area.remove(); } const old=button.textContent; button.textContent='Copied'; setTimeout(()=>{button.textContent=old;},1400); }); })();(() => { const b=document.querySelector('.legacy-menu-toggle'); if(!b)return; b.addEventListener('click',()=>{const o=document.body.classList.toggle('legacy-menu-open'); b.setAttribute('aria-expanded',String(o));}); })();
